#!/usr/bin/env bash
# Board job for docs/notes3 Loop 14: the sweep without the density/velocity outputs (plan lever C6),
# and the pystencils version of the Loop 12 code generation (HoistRowPointers, in_register).
#   screen -dmS notes3-lab7 bash misc/x60-lab/queue_lab7.sh
# Variants (gen.py, laptop): `+cg` = generated by the current pystencils (row pointers, constants
# in registers; QEMU: bit-identical to `+vf2`); `+nomacro` = the same kernel without the rho/u
# stores and their prefetch hints (wsum bit-identical to its base). Scalar AA baselines with and
# without outputs as well (the honesty clause: a non-vector lever applies to the scalar sweep too).
# The cg kernels need rvv::in_register, so they build against notes3/inc-cg (the laptop's
# pystencils runtime headers), whatever pystencils state the earlier jobs left.   -> notes3/lab7.log
set -u
REPO="$(cd "$(dirname "$0")/../.." && pwd)"
OUT=/home/bananapi/saleh/notes3
WAIT_FOR="${WAIT_FOR:-notes3-(e2e-cg|e2e-halo|lab6)}"
while screen -ls | grep -qE "${WAIT_FOR}"; do sleep 60; done

export PATH=/home/bananapi/saleh/venv/bin:$PATH XDG_CACHE_HOME=/home/bananapi/saleh/.cache
export INC="${OUT}/inc-cg"
cd "${REPO}/misc/x60-lab/lab"
export STEPS=40
{
   echo "== lab7: sweep without rho/u outputs, pystencils row pointers $(date)"
   for round in 1 2 3; do
      ro=1; [[ ${round} == 1 ]] && ro=0
      for dt in f32 f64; do
         TAG="lab7-r${round}" RUNONLY=1 RUNENV="AA=1" bash run.sh "${dt}-rvv-cse+aa+bpf=128+vf2"
         TAG="lab7-r${round}" RUNONLY=${ro} RUNENV="AA=1" bash run.sh \
            "${dt}-rvv-cse+aa+bpf=128+vf2+cg" "${dt}-rvv-cse+aa+bpf=128+vf2+cg+nomacro"
         TAG="lab7-r${round}" RUNONLY=1 bash run.sh "${dt}-rvv-cse+bpf=128+vf2"
         TAG="lab7-r${round}" RUNONLY=${ro} bash run.sh "${dt}-rvv-cse+bpf=128+vf2+cg" "${dt}-rvv-cse+bpf=128+vf2+cg+nomacro"
         TAG="lab7-r${round}" RUNONLY=${ro} RUNENV="AA=1" bash run.sh \
            "${dt}-generic-cse_scalar+aa" "${dt}-generic-cse_scalar+aa+nomacro"
         #  same-session references: the hand-written direction-split AA kernel (lab4 binaries),
         #  GCC and Clang + X60 tuning
         by=2; [[ ${dt} == f64 ]] && by=1
         for cc in gcc clang; do
            t=none; [[ ${cc} == clang ]] && t=spacemit-x60
            TAG="lab7-r${round}" CCS=${cc} RUNONLY=1 RUNENV="AA=1" bash run.sh "${dt}-hand-aa@BY-${by}_GM-5_GP-3_tune-${t}"
         done
      done
      #  the direction-split AA kernel generated with pystencils (gensplit.py): GCC sweep, and the
      #  main configuration with Clang + X60 tuning as well
      TAG="lab7-r${round}" RUNONLY=${ro} RUNENV="AA=1" bash run.sh f32-rvvsplit-by2gm5gp3 f32-rvvsplit-by2gm5gp2 \
         f32-rvvsplit-by2gm5gp5 f32-rvvsplit-by2gm7gp3 f32-rvvsplit-by1gm5gp3 f32-rvvsplit-by4gm5gp3 \
         "f32-rvvsplit-by2gm5gp3+pf=128" "f32-rvvsplit-by2gm5gp3+nomacro" \
         f64-rvvsplit-by1gm5gp3 f64-rvvsplit-by2gm5gp3 f64-rvvsplit-by1gm7gp3 f64-rvvsplit-by1gm5gp2 \
         "f64-rvvsplit-by1gm5gp3+pf=128" "f64-rvvsplit-by1gm5gp3+nomacro"
      TAG="lab7-r${round}" CCS=clang MARCH="-march=rv64gcv_zvl256b_zicbop -mtune=spacemit-x60" RUNONLY=${ro} \
         RUNENV="AA=1" bash run.sh f32-rvvsplit-by2gm5gp3 f64-rvvsplit-by1gm5gp3
   done
   echo "== done $(date)"
} > "${OUT}/lab7.log" 2>&1
